import{_ as l,a0 as o,w as p,s as n,ao as d,I as r,x as t,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"监测数据库的健康和行为：有哪些重要指标？ | LCTT x X-CMD","titleTemplate":false,"description":"监测数据库的健康和行为：有哪些重要指标？ | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"监测数据库的健康和行为：有哪些重要指标？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"监测数据库的健康和行为：有哪些重要指标？ | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181025 Monitoring database health and behavior- Which metrics matter","title":"监测数据库的健康和行为：有哪些重要指标？","tag":"201811","desc":""},"relativePath":"201811/20181025 Monitoring database health and behavior- Which metrics matter.md","filePath":"[post].md"}'),m={name:"201811/20181025 Monitoring database health and behavior- Which metrics matter.md"};function h(u,e,f,c,b,g){const a=o("Link");return p(),n("div",null,[e[15]||(e[15]=d('<h1 id="监测数据库的健康和行为-有哪些重要指标" tabindex="-1">监测数据库的健康和行为：有哪些重要指标？ <a class="header-anchor" href="#监测数据库的健康和行为-有哪些重要指标" aria-label="Permalink to “监测数据库的健康和行为：有哪些重要指标？”">​</a></h1><blockquote><p>对数据库的监测可能过于困难或者没有找到关键点。本文将讲述如何正确的监测数据库。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/metrics_graph_stats_blue.png?itok=OKCc_60D" alt=""></p><p>我们没有对数据库讨论过多少。在这个充满监测仪器的时代，我们监测我们的应用程序、基础设施、甚至我们的用户，但有时忘记我们的数据库也值得被监测。这很大程度是因为数据库表现的很好，以至于我们单纯地信任它能把任务完成的很好。信任固然重要，但能够证明它的表现确实如我们所期待的那样就更好了。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image1_-_bffs.png?itok=BZQM_Fos" alt=""></p><h3 id="为什么监测你的数据库" tabindex="-1">为什么监测你的数据库？ <a class="header-anchor" href="#为什么监测你的数据库" aria-label="Permalink to “为什么监测你的数据库？”">​</a></h3><p>监测数据库的原因有很多，其中大多数原因与监测系统的任何其他部分的原因相同：了解应用程序的各个组件中发生的什么，会让你成为更了解情况的，能够做出明智决策的开发人员。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image5_fire.png?itok=wsip2Fa4" alt=""></p><p>更具体地说，数据库是系统健康和行为的重要标志。数据库中的异常行为能够指出应用程序中出现问题的区域。另外，当应用程序中有异常行为时，你可以利用数据库的指标来迅速完成排除故障的过程。</p><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to “问题”">​</a></h3><p>最轻微的调查揭示了监测数据库的一个问题：数据库有很多指标。说“很多”只是轻描淡写，如果你是<ruby>史高治<rt>Scrooge McDuck</rt></ruby>（LCTT 译注：史高治，唐老鸭的舅舅，以一毛不拔著称），你不会放过任何一个可用的指标。如果这是<ruby>摔角狂热<rt>Wrestlemania</rt></ruby> 比赛，那么指标就是折叠椅。监测所有指标似乎并不实用，那么你如何决定要监测哪些指标？</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image2_db_metrics.png?itok=Jd9NY1bt" alt=""></p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to “解决方案”">​</a></h3><p>开始监测数据库的最好方式是认识一些基础的数据库指标。这些指标为理解数据库的行为创造了良好的开端。</p><h3 id="吞吐量-数据库做了多少" tabindex="-1">吞吐量：数据库做了多少？ <a class="header-anchor" href="#吞吐量-数据库做了多少" aria-label="Permalink to “吞吐量：数据库做了多少？”">​</a></h3><p>开始检测数据库的最好方法是跟踪它所接到请求的数量。我们对数据库有较高期望；期望它能稳定的存储数据，并处理我们抛给它的所有查询，这些查询可能是一天一次大规模查询，或者是来自用户一天到晚的数百万次查询。吞吐量可以告诉我们数据库是否如我们期望的那样工作。</p><p>你也可以将请求按照类型（读、写、服务器端、客户端等）分组，以开始分析流量。</p><h3 id="执行时间-数据库完成工作需要多长时间" tabindex="-1">执行时间：数据库完成工作需要多长时间？ <a class="header-anchor" href="#执行时间-数据库完成工作需要多长时间" aria-label="Permalink to “执行时间：数据库完成工作需要多长时间？”">​</a></h3><p>这个指标看起来很明显，但往往被忽视了。你不仅想知道数据库收到了多少请求，还想知道数据库在每个请求上花费了多长时间。 然而，参考上下文来讨论执行时间非常重要：像 InfluxDB 这样的时间序列数据库中的慢与像 MySQL 这样的关系型数据库中的慢不一样。InfluxDB 中的慢可能意味着毫秒，而 MySQL 的 <code>SLOW_QUERY</code> 变量的默认值是 10 秒。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image4_slow_is_relative.png?itok=9RkuzUi8" alt=""></p><p>监测执行时间和提高执行时间不一样，所以如果你的应用程序中有其他问题需要修复，那么请注意在优化上花费时间的诱惑。</p><h3 id="并发性-数据库同时做了多少工作" tabindex="-1">并发性：数据库同时做了多少工作？ <a class="header-anchor" href="#并发性-数据库同时做了多少工作" aria-label="Permalink to “并发性：数据库同时做了多少工作？”">​</a></h3><p>一旦你知道数据库正在处理多少请求以及每个请求需要多长时间，你就需要添加一层复杂性以开始从这些指标中获得实际值。</p><p>如果数据库接收到十个请求，并且每个请求需要十秒钟来完成，那么数据库是忙碌了 100 秒、10 秒，还是介于两者之间？并发任务的数量改变了数据库资源的使用方式。当你考虑连接和线程的数量等问题时，你将开始对数据库指标有更全面的了解。</p><p>并发性还能影响延迟，这不仅包括任务完成所需的时间（执行时间），还包括任务在处理之前需要等待的时间。</p><h3 id="利用率-数据库繁忙的时间百分比是多少" tabindex="-1">利用率：数据库繁忙的时间百分比是多少？ <a class="header-anchor" href="#利用率-数据库繁忙的时间百分比是多少" aria-label="Permalink to “利用率：数据库繁忙的时间百分比是多少？”">​</a></h3><p>利用率是由吞吐量、执行时间和并发性的峰值所确定的数据库可用的频率，或者数据库太忙而不能响应请求的频率。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image6_telephone.png?itok=YzdpwUQP" alt=""></p><p>该指标对于确定数据库的整体健康和性能特别有用。如果只能在 80% 的时间内响应请求，则可以重新分配资源、进行优化工作，或者进行更改以更接近高可用性。</p><h3 id="好消息" tabindex="-1">好消息 <a class="header-anchor" href="#好消息" aria-label="Permalink to “好消息”">​</a></h3><p>监测和分析似乎非常困难，特别是因为我们大多数人不是数据库专家，我们可能没有时间去理解这些指标。但好消息是，大部分的工作已经为我们做好了。许多数据库都有一个内部性能数据库（Postgres：<code>pg_stats</code>、CouchDB：<code>Runtime_Statistics</code>、InfluxDB：<code>_internal</code> 等），数据库工程师设计该数据库来监测与该特定数据库有关的指标。你可以看到像慢速查询的数量一样广泛的内容，或者像数据库中每个事件的平均微秒一样详细的内容。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>数据库创建了足够的指标以使我们需要长时间研究，虽然内部性能数据库充满了有用的信息，但并不总是使你清楚应该关注哪些指标。从吞吐量、执行时间、并发性和利用率开始，它们为你提供了足够的信息，使你可以开始了解你的数据库中的情况。</p><p><img src="https://opensource.com/sites/default/files/styles/medium/public/uploads/image3_3_hearts.png?itok=iHF-OSwx" alt=""></p><p>你在监视你的数据库吗？你发现哪些指标有用？告诉我吧！</p><hr>',36)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),s(a,{href:"https://opensource.com/article/18/10/database-metrics-matter"},{default:i(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/18/10/database-metrics-matter",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("作者：",-1)),s(a,{href:"https://opensource.com/users/thekatertot"},{default:i(()=>[...e[2]||(e[2]=[t("Katy Farmer",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),s(a,{href:"https://github.com/ChiZelin"},{default:i(()=>[...e[4]||(e[4]=[t("ChiZelin",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const T=l(m,[["render",h]]);export{k as __pageData,T as default};
